function initScriptsPage() {
  if (typeof window.__scriptsPageStopPolling === 'function') {
    try {
      window.__scriptsPageStopPolling();
    } catch (e) {
      console.error(e);
    }
  }

  var serviceRefreshTimer = 0;
  var serviceStatesController = null;
  var serviceRowsByScript = {};
  var SERVICE_POLL_VISIBLE_MS = 30000;

  function showServiceResult(content) {
    var message = String(content || '').replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
    if (window.showResult) window.showResult(message);
    else alert(message);
  }

  function parseJsonSafe(text) {
    try {
      return JSON.parse(text);
    } catch (e) {
      return null;
    }
  }

  function toBoolInt(value) {
    return value === true || value === 1 || value === '1';
  }

  function isHostActive() {
    var content = document.getElementById('content');
    if (window.isHostStillActive && !window.isHostStillActive(content)) {
      return false;
    }
    return true;
  }

  function clearServiceStatePolling() {
    if (serviceRefreshTimer) {
      clearTimeout(serviceRefreshTimer);
      serviceRefreshTimer = 0;
    }
    if (serviceStatesController) {
      serviceStatesController.abort();
      serviceStatesController = null;
    }
  }

  window.__scriptsPageStopPolling = clearServiceStatePolling;

  function rebuildServiceRowMap() {
    serviceRowsByScript = {};
    Array.prototype.slice.call(document.querySelectorAll('tr[data-script-name]')).forEach(function (row) {
      var scriptName = row.dataset.scriptName || '';
      if (scriptName) {
        serviceRowsByScript[scriptName] = row;
      }
    });
  }

  function getRowByScript(scriptName) {
    if (!scriptName) {
      return null;
    }
    return serviceRowsByScript[scriptName] || null;
  }

  // A stopped service is normal (most are optional); only failures and
  // services set to start at boot that are not running need attention.
  function rowHasProblem(row) {
    var state = row ? row.dataset.serviceState : "unknown";
    if (state === "running" || state === "loading" || state === "disabled") return false;
    if (state === "stopped") {
      var boot = row.querySelector('input.autostart');
      return !!(boot && boot.checked);
    }
    return true;
  }

  function updateServicesOverview() {
    var rows = Array.prototype.slice.call(document.querySelectorAll('tr[data-script-name]'));
    var running = 0;
    var stopped = 0;
    var problems = 0;
    rows.forEach(function (row) {
      var state = row.dataset.serviceState;
      if (state === 'running') running++;
      else if (state === 'stopped' || state === 'disabled') stopped++;
      if (rowHasProblem(row)) problems++;
    });
    var summary = document.getElementById('services_summary');
    if (summary) summary.textContent = running + ' running · ' + stopped + ' stopped' + (problems ? ' · ' + problems + ' need attention' : '');
    var issuesOnly = document.getElementById('services_issues_only');
    rows.forEach(function (row) { row.hidden = !!(issuesOnly && issuesOnly.checked && !rowHasProblem(row)); });
    SERVICE_POLL_VISIBLE_MS = problems ? 15000 : 45000;
  }

  function showServiceError(message) {
    var box = document.getElementById('services_error');
    var text = document.getElementById('services_error_text');
    if (text) text.textContent = message || 'Service request failed.';
    if (box) box.hidden = false;
  }

  function clearServiceError() {
    var box = document.getElementById('services_error');
    if (box) box.hidden = true;
  }

  function scheduleServiceStateRefresh(delayMs) {
    if (!isHostActive()) {
      clearServiceStatePolling();
      return;
    }
    if (serviceRefreshTimer) {
      clearTimeout(serviceRefreshTimer);
    }
    if (document.hidden) {
      clearServiceStatePolling();
      return;
    }
    var nextDelay = typeof delayMs === 'number' ? delayMs : SERVICE_POLL_VISIBLE_MS;
    serviceRefreshTimer = setTimeout(function () {
      serviceRefreshTimer = 0;
      refreshServiceStates();
    }, nextDelay);
  }

  function syncAutorunInput(row, stateInfo) {
    if (!row || !stateInfo) {
      return;
    }
    var autostartInput = row.querySelector('input.autostart');
    if (!autostartInput) {
      return;
    }
    autostartInput.checked = toBoolInt(stateInfo.autostart_enabled);
  }

  function formatUptime(s) {
    if (typeof s !== 'number' || s < 0) return '';
    if (s < 60) return s + 's';
    var m = Math.floor(s / 60);
    if (m < 60) return m + 'm';
    var h = Math.floor(m / 60);
    var rm = m % 60;
    if (h < 24) return h + 'h' + (rm ? ' ' + rm + 'm' : '');
    var d = Math.floor(h / 24);
    var rh = h % 24;
    return d + 'd' + (rh ? ' ' + rh + 'h' : '');
  }

  function updateStatusTag(tag, state, uptimeSecs) {
    if (!tag) {
      return;
    }

    tag.classList.remove('is-running', 'is-stopped', 'is-error', 'is-unknown');
    switch (state) {
      case 'running':
        tag.classList.add('is-running');
        var upLabel = formatUptime(uptimeSecs);
        tag.textContent = upLabel ? 'Running \u00b7 ' + upLabel : 'Running';
        tag.title = upLabel ? 'Running for ' + upLabel : 'Current state reported by this script';
        break;
      case 'stopped':
        tag.classList.add('is-stopped');
        tag.textContent = 'Stopped';
        tag.title = 'Current state reported by this script';
        break;
      case 'disabled':
        tag.classList.add('is-stopped');
        tag.textContent = 'Disabled';
        tag.title = 'Turned off in Settings (boot.conf); starts at boot once enabled there';
        break;
      case 'error':
        tag.classList.add('is-error');
        tag.textContent = 'Error';
        tag.title = 'Status probe returned an error';
        break;
      case 'timeout':
        tag.classList.add('is-error');
        tag.textContent = 'Timeout';
        tag.title = 'Status probe timed out';
        break;
      default:
        tag.classList.add('is-unknown');
        tag.textContent = 'Unknown';
        tag.title = 'Unable to determine service state';
        break;
    }
  }

  function updateActionButton(btn, scriptName, state, hasStart, hasStop) {
    if (!btn || !scriptName) {
      return;
    }

    var actionCmd = 'start';
    var actionLabel = 'Start';
    var actionClass = 'is-link';
    var actionHint = 'Start this service now.';
    var actionDisabled = false;

    if (state === 'running') {
      if (hasStop) {
        actionCmd = 'stop';
        actionLabel = 'Stop';
        actionClass = 'is-danger';
        actionHint = 'Stop this service now.';
      } else {
        actionLabel = 'Running';
        actionClass = 'is-light';
        actionHint = 'This service has no stop handler.';
        actionDisabled = true;
      }
    } else if (!hasStart) {
      actionLabel = 'N/A';
      actionClass = 'is-light';
      actionHint = 'This service has no start handler.';
      actionDisabled = true;
    }

    btn.classList.remove('is-link', 'is-danger', 'is-light');
    btn.classList.add(actionClass);
    btn.textContent = actionLabel;
    btn.title = actionHint;
    btn.dataset.target = 'cgi-bin/scripts.cgi?cmd=' + actionCmd + '&script=' + encodeURIComponent(scriptName);
    btn.disabled = !!actionDisabled;
  }

  function applyServiceState(row, stateInfo) {
    if (!row || !stateInfo) {
      return;
    }

    var scriptName = row.dataset.scriptName || '';
    var state = String(stateInfo.state || 'unknown').toLowerCase();
    var hasStart = toBoolInt(stateInfo.has_start);
    var hasStop = toBoolInt(stateInfo.has_stop);
    row.dataset.serviceState = state;

    updateStatusTag(row.querySelector('.service-status'), state, stateInfo.uptime_s);
    updateActionButton(row.querySelector('button.script_action_toggle'), scriptName, state, hasStart, hasStop);
    syncAutorunInput(row, stateInfo);
  }

  function refreshServiceState(row) {
    if (!row) {
      return Promise.resolve();
    }
    var scriptName = row.dataset.scriptName || '';
    if (!scriptName) {
      return Promise.resolve();
    }

    return fetch('cgi-bin/scripts.cgi?cmd=state&script=' + encodeURIComponent(scriptName), { cache: 'no-store' })
      .then(function (r) { return r.text(); })
      .then(function (text) {
        var json = parseJsonSafe(text);
        if (!json || json.status !== 'ok') {
          updateStatusTag(row.querySelector('.service-status'), 'unknown');
          return;
        }
        applyServiceState(row, json);
        updateServicesOverview();
      })
      .catch(function (err) {
        console.error(err);
        updateStatusTag(row.querySelector('.service-status'), 'unknown');
      });
  }

  function refreshServiceStates() {
    if (!isHostActive()) {
      clearServiceStatePolling();
      return;
    }

    if (serviceStatesController) {
      serviceStatesController.abort();
    }
    var controller = new AbortController();
    serviceStatesController = controller;

    fetch('cgi-bin/scripts.cgi?cmd=allstates', { cache: 'no-store', signal: controller.signal })
      .then(function (r) { return r.json(); })
      .then(function (json) {
        if (!isHostActive()) {
          return;
        }
        if (!json || json.status !== 'ok' || !Array.isArray(json.services)) {
          showServiceError('The camera returned an invalid service status.');
          return;
        }
        json.services.forEach(function (stateInfo) {
          var row = getRowByScript(stateInfo.script);
          if (row) applyServiceState(row, stateInfo);
        });
        clearServiceError();
        updateServicesOverview();
      })
      .catch(function (err) {
        if (err && err.name === 'AbortError') {
          return;
        }
        console.error('Service bulk poll error:', err);
        showServiceError('Service status is unavailable.');
      })
      .finally(function () {
        if (serviceStatesController === controller) {
          serviceStatesController = null;
        }
        scheduleServiceStateRefresh();
      });
  }

  rebuildServiceRowMap();
  var serviceBody = document.querySelector('.services-table tbody');
  if (serviceBody) {
    Array.prototype.slice.call(serviceBody.querySelectorAll('tr[data-essential="1"]')).forEach(function (row) { serviceBody.appendChild(row); });
    Array.prototype.slice.call(serviceBody.querySelectorAll('tr[data-essential="0"]')).forEach(function (row) { serviceBody.appendChild(row); });
  }
  var issuesOnly = document.getElementById('services_issues_only');
  if (issuesOnly) issuesOnly.addEventListener('change', updateServicesOverview);
  var retry = document.getElementById('services_retry');
  if (retry) retry.addEventListener('click', function () { clearServiceError(); refreshServiceStates(); });

  if (window.__scriptsPageVisibilityHandler) {
    document.removeEventListener('visibilitychange', window.__scriptsPageVisibilityHandler);
  }
  window.__scriptsPageVisibilityHandler = function () {
    if (!isHostActive() || document.hidden) clearServiceStatePolling();
    else scheduleServiceStateRefresh(0);
  };
  document.addEventListener('visibilitychange', window.__scriptsPageVisibilityHandler);

  Array.prototype.slice.call(document.querySelectorAll('button.script_action_toggle,button.script_action_stop,button.script_action_start')).forEach(function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.preventDefault();
      var e = ev.currentTarget;
      if (e.disabled) {
        return false;
      }
      e.disabled = true;
      e.classList.add('is-loading');
      var target = e.dataset.target;
      window.EliteUI.csrfFetch(target, { method: 'POST', cache: 'no-store' })
        .then(function (r) { return r.text(); })
        .then(function (res) {
          if (/\b(NOK|error|failed|invalid)\b/i.test(res)) throw new Error('Service command rejected');
          showServiceResult(res);
          clearServiceError();
          clearServiceStatePolling();
          var row = getRowByScript(e.dataset.scriptName || '');
          return refreshServiceState(row).then(function () { scheduleServiceStateRefresh(); });
        })
        .catch(function (err) {
          console.error(err);
          showServiceError('The service command failed. Retry or inspect the logs.');
        })
        .finally(function () {
          e.disabled = false;
          e.classList.remove('is-loading');
        });
      return false;
    });
  });

  Array.prototype.slice.call(document.querySelectorAll('input.autostart')).forEach(function (inp) {
    inp.addEventListener('change', function (ev) {
      var e = ev.currentTarget;
      var row = e.closest('tr[data-script-name]');
      var desiredState = e.checked;
      var url = desiredState ? e.dataset.checked : e.dataset.unchecked;
      e.disabled = true;
      window.EliteUI.csrfFetch(url, { method: 'POST', cache: 'no-store' })
        .then(function (r) { return r.text(); })
        .then(function (text) {
          var res = parseJsonSafe(text);
          if (!res || res.status !== 'ok') {
            e.checked = !desiredState;
            return;
          }
          if (typeof res.autostart_enabled !== 'undefined') {
            e.checked = toBoolInt(res.autostart_enabled);
          } else {
            e.checked = desiredState;
          }
          if (row) {
            refreshServiceState(row);
          }
          scheduleServiceStateRefresh(800);
        })
        .catch(function (err) {
          e.checked = !desiredState;
          console.error(err);
          showServiceError('The autorun change failed. Retry or inspect the logs.');
        })
        .finally(function () {
          e.disabled = false;
        });
    });
  });

  // "View" shows the script source in a dialog instead of a new tab. The link
  // keeps its href, so middle-click / open-in-new-tab still work.
  function getSourceDialog() {
    var dlg = document.getElementById('service_source_dialog');
    if (dlg) return dlg;
    dlg = document.createElement('dialog');
    dlg.id = 'service_source_dialog';
    dlg.className = 'source-dialog';
    dlg.innerHTML =
      '<div class="source-dialog-head">' +
        '<strong class="source-dialog-title"></strong>' +
        '<span class="source-dialog-meta"></span>' +
        '<button type="button" class="button is-small source-dialog-copy">Copy</button>' +
        '<button type="button" class="button is-small source-dialog-close" aria-label="Close" title="Close (Esc)">&times;</button>' +
      '</div>' +
      '<pre class="source-dialog-body"></pre>';
    document.body.appendChild(dlg);
    dlg.querySelector('.source-dialog-close').addEventListener('click', function () { dlg.close(); });
    // Click on the backdrop (outside the box) closes; Escape is native.
    dlg.addEventListener('click', function (ev) { if (ev.target === dlg) dlg.close(); });
    dlg.querySelector('.source-dialog-copy').addEventListener('click', function (ev) {
      var text = dlg.querySelector('.source-dialog-body').textContent;
      var btn = ev.currentTarget;
      var done = function () { btn.textContent = 'Copied'; setTimeout(function () { btn.textContent = 'Copy'; }, 1500); };
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(done, function () {});
      }
    });
    return dlg;
  }

  function showScriptSource(name) {
    var dlg = getSourceDialog();
    var body = dlg.querySelector('.source-dialog-body');
    dlg.querySelector('.source-dialog-title').textContent = name;
    dlg.querySelector('.source-dialog-meta').textContent = '';
    body.textContent = 'Loading…';
    if (typeof dlg.showModal === 'function') { if (!dlg.open) dlg.showModal(); } else { dlg.setAttribute('open', ''); }
    fetch('cgi-bin/scripts.cgi?cmd=source&script=' + encodeURIComponent(name), { cache: 'no-store' })
      .then(function (r) {
        if (!r.ok) throw new Error('HTTP ' + r.status);
        return r.text();
      })
      .then(function (text) {
        body.textContent = text;
        var lines = text ? text.split('\n').length : 0;
        dlg.querySelector('.source-dialog-meta').textContent = lines + ' lines';
        body.scrollTop = 0;
      })
      .catch(function (err) {
        body.textContent = 'Could not load the script source (' + (err && err.message ? err.message : err) + ').';
      });
  }

  Array.prototype.slice.call(document.querySelectorAll('.view_script')).forEach(function (el) {
    el.addEventListener('click', function (ev) {
      if (ev.ctrlKey || ev.metaKey || ev.shiftKey || ev.button === 1) return;   // let the browser open a tab
      ev.preventDefault();
      var name = ev.currentTarget.getAttribute('data-script-name');
      if (!name) {
        var m = /[?&]script=([^&]+)/.exec(ev.currentTarget.getAttribute('href') || '');
        name = m ? decodeURIComponent(m[1]) : '';
      }
      if (name) showScriptSource(name);
      return false;
    });
  });

  refreshServiceStates();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initScriptsPage);
} else {
  initScriptsPage();
}
